cypher_final:
MATCH (s:SetorCensitario)-[:PARTE_DE*3..4]->(m:Municipio)
WHERE (s)-[:TEM_PERFIL]->(p:PerfilDomiciliosParte1) AND p.v00002 > 100
  AND NOT EXISTS { MATCH (e:EquipamentoSaude)-[:LOCALIZADA_EM]->(s) }
  AND NOT EXISTS { MATCH (es:Escola)-[:LOCALIZADA_EM]->(s) }
  AND NOT EXISTS { MATCH (us:EquipamentoSaude)-[:LOCALIZADA_EM]->(s) }
RETURN s.cd_setor AS setor

MATCH (s:SetorCensitario)-[:PARTE_DE*3..4]->(m:Municipio)
WHERE s.situacao = 'Urbana'
  AND EXISTS { MATCH (:Escola)-[:LOCALIZADA_EM]->(s) }
  AND NOT EXISTS { MATCH (u:EquipamentoSaude)-[:LOCALIZADA_EM]->(s) WHERE u.at_04_conv_01 = true }
  AND EXISTS { MATCH (s)-[:TEM_PERFIL]->(p:PerfilDemografia) WHERE p.v01041 > 100 }
RETURN m.nm_mun AS municipio, s.cd_setor AS setor

MATCH (e:Escola)-[:LOCALIZADA_EM]->(s:SetorCensitario)-[:PARTE_DE*3..4]->(m:Municipio)
WHERE NOT EXISTS {
  MATCH (u:EquipamentoSaude)-[:LOCALIZADA_EM]->(s2:SetorCensitario)-[:PARTE_DE*3..4]->(m)
  WHERE u.at_06_conv_01 = true AND point.distance(e.location, u.location) <= 5000
}
RETURN e.id_aparelho AS codigo, e.nm_aparelho AS escola
